parameters.inputSchema:
{
	"type": "object",
	"properties": {
		"isAIGenerated": {
			"type": "boolean",
			"description": "Whether the resume appears to be AI-generated"
		},
		"confidenceScore": {
			"type": "number",
			"minimum": 0,
			"maximum": 100,
			"description": "Confidence score between 0-100"
		},
		"indicators": {
			"type": "array",
			"items": {
				"type": "string"
			},
			"description": "List of indicators found in the resume"
		},
		"reasoning": {
			"type": "string",
			"description": "Explanation of the detection reasoning"
		},
		"recommendation": {
			"type": "string",
			"description": "Recommendation based on the analysis"
		},
		"wordPatternScore": {
			"type": "number",
			"minimum": 0,
			"maximum": 100,
			"description": "Score indicating word pattern analysis"
		},
		"grammarConsistencyScore": {
			"type": "number",
			"minimum": 0,
			"maximum": 100,
			"description": "Score indicating grammar consistency"
		},
		"formattingAnalysis": {
			"type": "string",
			"description": "Analysis of document formatting patterns"
		},
		"linguisticMarkers": {
			"type": "array",
			"items": {
				"type": "string"
			},
			"description": "List of linguistic markers detected"
		},
		"sentenceComplexityVariance": {
			"type": "number",
			"description": "Variance in sentence complexity throughout the document"
		}
	},
	"required": ["isAIGenerated", "confidenceScore", "indicators", "reasoning", "recommendation"]
}
